const ERL_NEW: string = "// /source/memory-store.ts\n// A memory store for hit counts\n\nimport type { ClientRateLimitInfo, Options, Store } from './types.js'\nimport type { Validations } from './validations.js'\n\n/**\n * The record that stores information about a client - namely, how many times\n * they have hit the endpoint, and when their hit count resets.\n *\n * Similar to `ClientRateLimitInfo`, except `resetTime` is a compulsory field.\n */\ntype Client = {\n\ttotalHits: number\n\tresetTime: Date\n}\n\n/**\n * A `Store` that stores the hit count for each client in memory.\n *\n * @public\n */\nexport class MemoryStore implements Store {\n\t/**\n\t * The duration of time before which all hit counts are reset (in milliseconds).\n\t */\n\twindowMs!: number\n\n\t/**\n\t * These two maps store usage (requests) and reset time by key (for example, IP\n\t * addresses or API keys).\n\t *\n\t * They are split into two to avoid having to iterate through the entire set to\n\t * determine which ones need reset. Instead, `Client`s are moved from `previous`\n\t * to `current` as they hit the endpoint. Once `windowMs` has elapsed, all clients\n\t * left in `previous`, i.e., those that have not made any recent requests, are\n\t * known to be expired and can be deleted in bulk.\n\t */\n\tprevious = new Map<string, Client>()\n\tcurrent = new Map<string, Client>()\n\n\t/**\n\t * A reference to the active timer.\n\t */\n\tinterval?: NodeJS.Timeout\n\n\t/**\n\t * Confirmation that the keys incremented in once instance of MemoryStore\n\t * cannot affect other instances.\n\t */\n\tlocalKeys = true\n\n\tconstructor(private validations?: Validations) {}\n\n\t/**\n\t * Method that initializes the store.\n\t *\n\t * @param options {Options} - The options used to setup the middleware.\n\t */\n\tinit(options: Options): void {\n\t\t// Get the duration of a window from the options.\n\t\tthis.windowMs = options.windowMs\n\n\t\t// check for a valid value\n\t\tthis.validations?.windowMs(this.windowMs)\n\n\t\t// Indicates that init was called more than once.\n\t\t// Could happen if a store was shared between multiple instances.\n\t\tif (this.interval) clearInterval(this.interval)\n\n\t\t// Reset all clients left in previous every `windowMs`.\n\t\tthis.interval = setInterval(() => {\n\t\t\tthis.clearExpired()\n\t\t}, this.windowMs)\n\n\t\t// Cleaning up the interval will be taken care of by the `shutdown` method.\n\t\tthis.interval.unref?.()\n\t}\n\n\t/**\n\t * Method to fetch a client's hit count and reset time.\n\t *\n\t * @param key {string} - The identifier for a client.\n\t *\n\t * @returns {ClientRateLimitInfo | undefined} - The number of hits and reset time for that client.\n\t *\n\t * @public\n\t */\n\tasync get(key: string): Promise<ClientRateLimitInfo | undefined> {\n\t\tconst client = this.current.get(key) ?? this.previous.get(key)\n\n\t\t// A client whose window has ended may still be held in memory until the\n\t\t// next cleanup, but its hit count no longer applies.\n\t\tif (client && client.resetTime.getTime() <= Date.now()) return undefined\n\n\t\treturn client\n\t}\n\n\t/**\n\t * Method to increment a client's hit counter.\n\t *\n\t * @param key {string} - The identifier for a client.\n\t *\n\t * @returns {ClientRateLimitInfo} - The number of hits and reset time for that client.\n\t *\n\t * @public\n\t */\n\tasync increment(key: string): Promise<ClientRateLimitInfo> {\n\t\tconst client = this.getClient(key)\n\n\t\tconst now = Date.now()\n\t\tif (client.resetTime.getTime() <= now) {\n\t\t\tthis.resetClient(client, now)\n\t\t}\n\n\t\tclient.totalHits++\n\t\treturn client\n\t}\n\n\t/**\n\t * Method to decrement a client's hit counter.\n\t *\n\t * @param key {string} - The identifier for a client.\n\t *\n\t * @public\n\t */\n\tasync decrement(key: string): Promise<void> {\n\t\tconst client = this.getClient(key)\n\n\t\tif (client.totalHits > 0) client.totalHits--\n\t}\n\n\t/**\n\t * Method to reset a client's hit counter.\n\t *\n\t * @param key {string} - The identifier for a client.\n\t *\n\t * @public\n\t */\n\tasync resetKey(key: string): Promise<void> {\n\t\tthis.current.delete(key)\n\t\tthis.previous.delete(key)\n\t}\n\n\t/**\n\t * Method to reset everyone's hit counter.\n\t *\n\t * @public\n\t */\n\tasync resetAll(): Promise<void> {\n\t\tthis.current.clear()\n\t\tthis.previous.clear()\n\t}\n\n\t/**\n\t * Method to stop the timer (if currently running) and prevent any memory\n\t * leaks.\n\t *\n\t * @public\n\t */\n\tshutdown(): void {\n\t\tclearInterval(this.interval)\n\t\tvoid this.resetAll()\n\t}\n\n\t/**\n\t * Recycles a client by setting its hit count to zero, and reset time to\n\t * `windowMs` milliseconds from now.\n\t *\n\t * NOT to be confused with `#resetKey()`, which removes a client from both the\n\t * `current` and `previous` maps.\n\t *\n\t * @param client {Client} - The client to recycle.\n\t * @param now {number} - The current time, to which the `windowMs` is added to get the `resetTime` for the client.\n\t *\n\t * @return {Client} - The modified client that was passed in, to allow for chaining.\n\t */\n\tprivate resetClient(client: Client, now = Date.now()): Client {\n\t\tclient.totalHits = 0\n\t\tclient.resetTime = new Date(now + this.windowMs)\n\n\t\treturn client\n\t}\n\n\t/**\n\t * Retrieves or creates a client, given a key. Also ensures that the client being\n\t * returned is in the `current` map.\n\t *\n\t * @param key {string} - The key under which the client is (or is to be) stored.\n\t *\n\t * @returns {Client} - The requested client.\n\t */\n\tprivate getClient(key: string): Client {\n\t\t// If we already have a client for that key in the `current` map, return it.\n\t\t// biome-ignore lint/style/noNonNullAssertion: we're checking that it exists\n\t\tif (this.current.has(key)) return this.current.get(key)!\n\n\t\tlet client\n\t\tif (this.previous.has(key)) {\n\t\t\t// If it's in the `previous` map, take it out\n\t\t\t// biome-ignore lint/style/noNonNullAssertion: we're checking that it exists\n\t\t\tclient = this.previous.get(key)!\n\t\t\tthis.previous.delete(key)\n\t\t} else {\n\t\t\t// Finally, if we don't have an existing entry for this client, create a new one\n\t\t\tclient = { totalHits: 0, resetTime: new Date() }\n\t\t\tthis.resetClient(client)\n\t\t}\n\n\t\t// Make sure the client is bumped into the `current` map, and return it.\n\t\tthis.current.set(key, client)\n\t\treturn client\n\t}\n\n\t/**\n\t * Move current clients to previous, create a new map for current.\n\t *\n\t * This function is called every `windowMs`.\n\t */\n\tprivate clearExpired(): void {\n\t\t// At this point, all clients in previous are expired\n\t\tthis.previous = this.current\n\t\tthis.current = new Map()\n\t}\n}\n";

/** Pass the element's type when cloning a tag. A check that is not cloneNode is refused. */
export function preserveElementTypeOnClone(source: string): string | null {
  if (!source.includes("export function cloneNode")) return null;
  return source === DOMHANDLER_OLD ? DOMHANDLER_NEW : null;
}

/** Use the value's constructor for an empty SharedArrayBuffer. A check that is not copyArrayBuffer is refused. */
export function copyEmptySharedArrayBufferSubclass(source: string): string | null {
  if (!source.includes("export function copyArrayBuffer")) return null;
  return source === FASTCOPY_OLD ? FASTCOPY_NEW : null;
}

/** Skip a MemoryStore client whose window has already ended. A check that is not MemoryStore is refused. */
export function skipExpiredMemoryStoreClients(source: string): string | null {
  if (!source.includes("export class MemoryStore")) return null;
  return source === ERL_OLD ? ERL_NEW : null;
}

export interface Batch32Input {
  root: string;
  output: string;
  sourcePattern?: string;
  nodePath: string;
  nodeModules?: string | null;
  testCommand: readonly string[];
  bwrap?: string;
}

function readLocal(dir: string, path: string): string | null {
  try {
    return readFileSync(join(dir, path), "utf8");
  } catch {
    return null;
  }
}

function filesOf(dir: string, pattern: string | undefined): string[] {
  const listed = practiceGit(dir, ["ls-files"]);
  if (!listed.ok) return [];
  return listed.out.split("\n").map((p) => p.trim()).filter((p) => /\.(?:tsx?|js)$/.test(p) && !p.endsWith(".d.ts") && (!pattern || new RegExp(pattern).test(p)));
}

/** Apply the one repair the failure can prove, then require the published test to pass in the sandbox. */
export function repairBatch32(input: Batch32Input): { diff: string; file: string } | null {
  if (!/Error|not equal|Expected|Invalid|fail|toEqual|toBe|AssertionError|TypeError|script|style|tag|SharedArrayBuffer|toBeInstanceOf|toBeUndefined|expired|undefined|totalHits/i.test(input.output)) return null;
  const edits: { path: string; next: string; original: string }[] = [];
  for (const path of filesOf(input.root, input.sourcePattern)) {
    const original = readLocal(input.root, path);
    if (original === null) continue;
    const next = preserveElementTypeOnClone(original) ?? copyEmptySharedArrayBufferSubclass(original) ?? skipExpiredMemoryStoreClients(original);
    if (next && next !== original) edits.push({ path, next, original });
  }
  if (edits.length !== 1) return null;
  const edit = edits[0]!;
  try {
    writeFileSync(join(input.root, edit.path), edit.next);
    const again = runInPracticeSandbox(input.root, input.testCommand, 180_000, {
      capture: true, nodePath: input.nodePath, nodeModules: input.nodeModules, ...(input.bwrap ? { bwrap: input.bwrap } : {}),
    });
    if (again.unsafe || again.code !== 0) return null;
    const diff = practiceGit(input.root, ["diff", "--no-color", "--no-ext-diff", "--no-renames", "--", edit.path]);
    if (!diff.ok || !diff.out.trim()) return null;
    return { diff: diff.out, file: edit.path };
  } finally {
    writeFileSync(join(input.root, edit.path), edit.original);
  }
}
